      normalizedArgs.source ??
      normalizedArgs.from ??
      "",
  );
  const destination = String(
    normalizedArgs.destination ??
      normalizedArgs.new_path ??
      normalizedArgs.to ??
      "",
  );
  const detail =
    command ||
    (source && destination
      ? `${source} -> ${destination}`
      : source || destination);

  return Object.freeze({
    tool: String(tool || "unknown").trim() || "unknown",
    args: normalizedArgs,
    command,
    source,
    destination,
    detail,
  });
}

