/**
 * verify-19 —「取消审批迟到回调」
 *
 * Behavioral regression coverage for the approval-grant ledger, which is the
 * unit where a late/cancelled acceptance could otherwise authorize a *new*
 * request. Two acceptance criteria are exercised through the public
 * `ApprovalGrantLedger` surface (import resolved relative to this file):
 *
 *   1. 正常接受仅绑定原请求 — an acceptance grants *only* the original
 *      request's permission (other permissions offered in the same verdict are
 *      not granted) and records the original request's binding on that grant.
 *   2. 取消后迟到接受不能授权新请求 — a grant that has been cancelled
 *      (revoked) no longer authorizes a subsequent request; it is not
 *      resurrected by a persistence round-trip, and a turn-scoped acceptance
 *      is not persisted to the session ledger.
 *
 * No source is modified. Import path is relative to this deliverable:
 * `../src/lib/approval-grant-ledger.js`.
 */
import { describe, it, expect } from "vitest";
import {
  ApprovalGrantLedger,
  approvalPermissionForContext,
} from "../src/lib/approval-grant-ledger.js";

const NOW = 1_700_000_000_000;

function makeLedger(sessionId = "sess-19") {
  return new ApprovalGrantLedger({ sessionId, now: () => NOW });
}

describe("verify-19 — 取消审批迟到回调", () => {
  it("正常接受仅授权原请求所需权限（其余候选不被授予）", () => {
    const ledger = makeLedger();
    const original = approvalPermissionForContext(
      { tool: "shell", args: { command: "ls" } },
      { cwd: "/work" },
    );
    // A different tool call in the same session → different args → different
    // scope → a genuinely different permission that must NOT be granted.
    const other = approvalPermissionForContext(
      { tool: "shell", args: { command: "rm -rf /" } },
      { cwd: "/work" },
    );

    const applied = ledger.applyDecision(
      { kind: "acceptForSession", permissions: [other, original] },
      original,
      "binding-original",
    );

    expect(applied.granted).toEqual([original]);
    // Only the original request's permission is authorized; the other offered
    // permission is untouched even though the verdict mentioned it.
    expect(ledger.allows(original)).toBe(true);
    expect(ledger.allows(other)).toBe(false);
  });

  it("正常接受将原请求绑定记录在授权项上", () => {
    const ledger = makeLedger();
    const original = approvalPermissionForContext(
      { tool: "shell", args: { command: "ls" } },
      { cwd: "/work" },
    );

    ledger.applyDecision(
      { kind: "acceptForSession", permissions: [original] },
      original,
      "binding-original",
    );

    const grants = ledger.listGrants();
    expect(grants).toHaveLength(1);
    expect(grants[0].binding).toBe("binding-original");
    // Binding survives serialization (persistence) unchanged.
    expect(ledger.toJSON().grants[0].binding).toBe("binding-original");
  });

  it("改变参数的新请求不被已绑定授权项覆盖（仅绑定原请求）", () => {
    const ledger = makeLedger();
    const original = approvalPermissionForContext(
      { tool: "shell", args: { command: "ls" } },
      { cwd: "/work" },
    );
    // Change ONLY the args of the follow-up request; cwd/tool/policy stay valid.
    const differentArgs = approvalPermissionForContext(
      { tool: "shell", args: { command: "ls -la" } },
      { cwd: "/work" },
    );

    ledger.applyDecision(
      { kind: "acceptForSession", permissions: [original] },
      original,
      "binding-original",
    );

    expect(ledger.allows(original)).toBe(true);
    // A new request with different args is NOT authorized: the grant is bound
    // to the original request only.
    expect(ledger.allows(differentArgs)).toBe(false);
  });

  it("取消（撤销）后的授权项不再授权后续请求", () => {
    const ledger = makeLedger();
    const original = approvalPermissionForContext(
      { tool: "shell", args: { command: "ls" } },
      { cwd: "/work" },
    );

    ledger.applyDecision(
      { kind: "acceptForSession", permissions: [original] },
      original,
      "binding-original",
    );
    const grantId = ledger.listGrants()[0].grantId;

    // Cancellation (revoke) succeeds and removes the grant.
    expect(ledger.revoke(grantId).revoked).toBe(true);
    expect(ledger.listGrants()).toEqual([]);
    // A subsequent (even identical) request is NOT authorized: the cancelled
    // acceptance cannot authorize a new request.
    expect(ledger.allows(original)).toBe(false);
  });

  it("被取消的授权项不会因持久化往返而复活", () => {
    const ledger = makeLedger();
    const original = approvalPermissionForContext(
      { tool: "shell", args: { command: "ls" } },
      { cwd: "/work" },
    );
    const sessionId = "sess-19";

    ledger.applyDecision(
      { kind: "acceptForSession", permissions: [original] },
      original,
      "binding-original",
    );
    ledger.revoke(ledger.listGrants()[0].grantId);

    // Persist the post-revoke ledger and reload it: the revoked grant is gone.
    const restored = ApprovalGrantLedger.fromJSON(ledger.toJSON(), {
      sessionId,
      now: () => NOW,
    });
    expect(restored.listGrants()).toEqual([]);
    expect(restored.allows(original)).toBe(false);
  });

  it("turn 级接受不写入会话授权，不覆盖新请求", () => {
    const ledger = makeLedger();
    const original = approvalPermissionForContext(
      { tool: "shell", args: { command: "ls" } },
      { cwd: "/work" },
    );

    const applied = ledger.applyDecision(
      { kind: "acceptForTurn", permissions: [original] },
      original,
      "binding-turn",
    );
    expect(applied.persistedScope).toBe(false);
    // Available within the turn…
    expect(ledger.allows(original)).toBe(true);
    // …but not persisted as a session grant, so it cannot authorize a new
    // session's request.
    expect(ledger.toJSON().grants).toEqual([]);
  });
});

function livePermission(permission, now) {
  const validation = validateAppServerDefinition("PermissionGrant", permission);
  if (!validation.ok) return false;
  return !permission.expiresAt || Date.parse(permission.expiresAt) > now;
}

function samePermission(left, right) {
  return permissionKey(left) === permissionKey(right);
}

function normalizePersistedEntry(entry, now) {
  if (!entry || typeof entry !== "object" || Array.isArray(entry)) return null;
  if (!livePermission(entry.permission, now)) return null;
  if (
    typeof entry.binding !== "string" ||
    !entry.binding ||
    typeof entry.grantedAt !== "string" ||
    Number.isNaN(Date.parse(entry.grantedAt))
  ) {
    return null;
  }
  return Object.freeze({
    permission: Object.freeze({ ...entry.permission }),
    binding: entry.binding,
    grantedAt: entry.grantedAt,
  });
}

export class ApprovalGrantLedger {
  constructor({ sessionId, now = () => Date.now() } = {}) {
    if (!sessionId) throw new TypeError("approval grant sessionId is required");
    this.sessionId = String(sessionId);
    this.now = now;
    this.turnId = null;
    this.turnGrants = new Map();
    this.sessionGrants = new Map();
    this.revision = 0;
  }

  beginTurn(turnId) {
    this.turnId = String(turnId);
    this.turnGrants.clear();
  }

  allows(permission) {
    const now = this.now();
    const key = permissionKey(permission);
    for (const grants of [this.turnGrants, this.sessionGrants]) {
      const entry = grants.get(key);
      if (!entry) continue;
      if (livePermission(entry.permission, now)) return true;
      grants.delete(key);
    }
    return false;
  }

  listGrants() {
    const now = this.now();
    const grants = [];
    for (const [lifetime, entries] of [
      ["turn", this.turnGrants],
      ["session", this.sessionGrants],
    ]) {
      for (const [key, entry] of entries) {
        if (!livePermission(entry.permission, now)) {
          entries.delete(key);
          continue;
        }
        grants.push(
          Object.freeze({
            grantId: grantId(this.sessionId, lifetime, entry.permission),
            lifetime,
            permission: Object.freeze({ ...entry.permission }),
            binding: entry.binding,
            grantedAt: entry.grantedAt,
            ...(lifetime === "turn" ? { turnId: this.turnId } : {}),
          }),
        );
      }
    }
    return Object.freeze(grants);
  }

  revoke(grantIdValue) {
    const requestedId = String(grantIdValue || "");
    for (const [lifetime, entries] of [
      ["turn", this.turnGrants],
      ["session", this.sessionGrants],
    ]) {
      for (const [key, entry] of entries) {
        if (
          grantId(this.sessionId, lifetime, entry.permission) !== requestedId
        ) {
          continue;
        }
        entries.delete(key);
        if (lifetime === "session") this.revision += 1;
        return Object.freeze({
          revoked: true,
          persistedScope: lifetime === "session",
          grant: Object.freeze({
            grantId: requestedId,
            lifetime,
            permission: Object.freeze({ ...entry.permission }),
            binding: entry.binding,
            grantedAt: entry.grantedAt,
          }),
        });
      }
    }
    return Object.freeze({
      revoked: false,
      persistedScope: false,
      grant: null,
    });
  }

  applyDecision(decision, requiredPermission, binding) {
    if (
      decision?.kind !== "acceptForTurn" &&
      decision?.kind !== "acceptForSession"
    ) {
      return Object.freeze({
        decision,
        granted: Object.freeze([]),
        persistedScope: false,
      });
    }
    const candidates =
      decision.permissions === undefined
        ? [requiredPermission]
        : decision.permissions;
    const target =
      decision.kind === "acceptForSession"
        ? this.sessionGrants
        : this.turnGrants;

/**
 * Canonicalize the part of a tool request that is classified and shown to the
 * user for approval. Keeping this in one place prevents the safety classifier
 * and the permission prompt from silently reasoning about different inputs.
 */

function quoteArgvToken(value) {
  const token = String(value);
  if (token && !/[\s|;&"'\\]/u.test(token)) return token;
  return `"${token.replace(/\\/gu, "\\\\").replace(/"/gu, '\\"')}"`;
}

export function normalizePermissionRequest({ tool, args } = {}) {
  const normalizedArgs = args && typeof args === "object" ? args : {};
  const command =
    typeof normalizedArgs.command === "string"
      ? normalizedArgs.command
      : Array.isArray(normalizedArgs.argv)
        ? normalizedArgs.argv.map(quoteArgvToken).join(" ")
        : "";
  const source = String(
    normalizedArgs.path ??
      normalizedArgs.file_path ??
      normalizedArgs.source ??
      normalizedArgs.from ??
      "",
  );
  const destination = String(
    normalizedArgs.destination ??
      normalizedArgs.new_path ??
      normalizedArgs.to ??
      "",
  );
  const detail =
    command ||
    (source && destination
      ? `${source} -> ${destination}`
      : source || destination);

  return Object.freeze({
    tool: String(tool || "unknown").trim() || "unknown",
    args: normalizedArgs,
    command,
    source,
    destination,
    detail,
  });
}

